// Package logread reads Drydock's JSON Lines LLM execution log into Records.
//
// It never writes to the log it reads. Blank lines are ignored; malformed lines are
// skipped with a diagnostic on the warning writer.
package logread

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

// Record is one execution from the log, normalized for reporting.
type Record struct {
	ExecutionID    string
	StartedAt      string
	Date           string
	Status         string
	Failed         bool
	Command        string
	Target         string
	Provider       string
	RequestedModel string
	Model          string
	InputTokens    int64
	CachedTokens   int64
	OutputTokens   int64
	CostUSD        float64
	ElapsedMS      int64
	ReturnCode     *int
	TimedOut       bool
}

// Result is what Read produced from a log: the decoded records and the number of skipped lines.
type Result struct {
	Records []Record
	Skipped int
}

// wireLine mirrors one JSON Lines object. Absent fields decode to their zero value.
type wireLine struct {
	ExecutionID string `json:"execution_id"`
	StartedAt   string `json:"started_at"`
	Status      string `json:"status"`
	Job         struct {
		CommandName string `json:"command_name"`
		Target      string `json:"target"`
		LLM         string `json:"llm"`
		Model       string `json:"model"`
	} `json:"job"`
	Result struct {
		ReturnCode *int `json:"returncode"`
		TimedOut   bool `json:"timed_out"`
		Stats      struct {
			CachedInputTokens int64   `json:"cached_input_tokens"`
			ElapsedMS         int64   `json:"elapsed_ms"`
			InputTokens       int64   `json:"input_tokens"`
			OutputTokens      int64   `json:"output_tokens"`
			CostUSD           float64 `json:"cost_usd"`
			Model             string  `json:"model"`
		} `json:"stats"`
	} `json:"result"`
}

// Read decodes every non-blank line of r as one log record. Malformed lines are counted in
// Result.Skipped and described on warn. The error is non-nil only when reading from r fails.
func Read(r io.Reader, warn io.Writer) (Result, error) {
	if warn == nil {
		warn = io.Discard
	}
	var res Result
	br := bufio.NewReader(r)
	for lineNo := 1; ; lineNo++ {
		line, err := br.ReadBytes('\n')
		if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
			rec, perr := parseLine(trimmed)
			if perr != nil {
				res.Skipped++
				fmt.Fprintf(warn, "line %d: skipped: %v\n", lineNo, perr)
			} else {
				res.Records = append(res.Records, rec)
			}
		}
		if errors.Is(err, io.EOF) {
			return res, nil
		}
		if err != nil {
			return res, err
		}
	}
}

// parseLine decodes one non-blank, whitespace-trimmed line into a Record.
func parseLine(data []byte) (Record, error) {
	if data[0] != '{' {
		return Record{}, errors.New("not a JSON object")
	}
	var w wireLine
	if err := json.Unmarshal(data, &w); err != nil {
		return Record{}, err
	}
	return Record{
		ExecutionID:    w.ExecutionID,
		StartedAt:      w.StartedAt,
		Date:           firstRunes(w.StartedAt, 10),
		Status:         w.Status,
		Failed:         w.Status != "succeeded",
		Command:        w.Job.CommandName,
		Target:         w.Job.Target,
		Provider:       w.Job.LLM,
		RequestedModel: w.Job.Model,
		Model:          w.Result.Stats.Model,
		InputTokens:    w.Result.Stats.InputTokens,
		CachedTokens:   w.Result.Stats.CachedInputTokens,
		OutputTokens:   w.Result.Stats.OutputTokens,
		CostUSD:        w.Result.Stats.CostUSD,
		ElapsedMS:      w.Result.Stats.ElapsedMS,
		ReturnCode:     w.Result.ReturnCode,
		TimedOut:       w.Result.TimedOut,
	}, nil
}

// firstRunes returns the first n characters of s, or all of s when it is shorter.
func firstRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		r = r[:n]
	}
	return string(r)
