	got := mustParse(t, "summary", "log.jsonl")
	want := cli.Options{Report: "summary", LogPath: "log.jsonl"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Options = %+v, want %+v", got, want)
	}
}

