	expectUsageError(t, "summary", "--since", "2026-02-30", "log.jsonl")
	expectUsageError(t, "summary", "--until", "2027-02-29", "log.jsonl")
	expectUsageError(t, "summary", "--until", "2026-04-31", "log.jsonl")
}

